const width = 900;
const height = 760;
const svg = d3.select('#bubble-chart');
const tooltip = d3.select('#tooltip');

let selectedTicker = null;

const sectorCenters = {
  'Information Technology': { x: width * 0.35, y: height * 0.28 },
  'Industry': { x: width * 0.65, y: height * 0.28 },
  'Energy': { x: width * 0.35, y: height * 0.62 },
  'Financial': { x: width * 0.65, y: height * 0.62 },
  'ETF': { x: width * 0.5, y: height * 0.45 }
};

const sectorOrder = ['Information Technology', 'Industry', 'Energy', 'Financial', 'ETF'];

const color = d3.scaleOrdinal()
  .domain(sectorOrder)
  .range(['#4e79a7', '#59a14f', '#e15759', '#f28e2b', '#b07aa1']);

function formatMarketCap(value) {
  if (!value || isNaN(value)) {
    return 'N/A';
  }

  const abs = Math.abs(value);

  if (abs >= 1e12) {
    return `${(value / 1e12).toFixed(2)}T`;
  }

  if (abs >= 1e9) {
    return `${(value / 1e9).toFixed(2)}B`;
  }

  if (abs >= 1e6) {
    return `${(value / 1e6).toFixed(2)}M`;
  }

  return d3.format(',')(value);
}

function renderSelection() {
  d3.selectAll('g.node')
    .classed('selected', d => d.ticker === selectedTicker)
    .classed('dimmed', d => selectedTicker && d.ticker !== selectedTicker);

  d3.selectAll('#stock-table tbody tr')
    .classed('selected', d => d.ticker === selectedTicker);

  const row = d3.selectAll('#stock-table tbody tr')
    .filter(d => d.ticker === selectedTicker)
    .node();

  if (row) {
    row.scrollIntoView({ block: 'nearest' });
  }
}

function setSelected(ticker) {
  selectedTicker = selectedTicker === ticker ? null : ticker;
  renderSelection();
}

function addLegend() {
  const legend = svg.append('g')
    .attr('class', 'legend')
    .attr('transform', 'translate(20, 20)');

  const items = legend.selectAll('g')
    .data(sectorOrder)
    .enter()
    .append('g')
    .attr('transform', (_, i) => `translate(0, ${i * 26})`);

  items.append('rect')
    .attr('width', 16)
    .attr('height', 16)
    .attr('fill', d => color(d));

  items.append('text')
    .attr('x', 24)
    .attr('y', 12)
    .text(d => d);
}

function showTooltip(event, d) {
  if (d.sector === 'ETF') {
    return;
  }

  tooltip
    .classed('visible', true)
    .html(`
      <strong>${d.ticker}</strong><br>
      ${d.fullName}<br>
      Sector: ${d.sector}
    `)
    .style('left', `${event.pageX - 40}px`)
    .style('top', `${event.pageY - 80}px`);
}

function hideTooltip() {
  tooltip.classed('visible', false);
}

Promise.all([
  d3.csv('data/stock-descriptions.csv')
]).then(([raw]) => {
  const data = raw
    .map(d => ({
      ticker: d.ticker,
      sector: d.sector,
      fullName: d['full name'],
      marketCap: d.marketCap ? +d.marketCap : null
    }))
    .sort((a, b) => d3.ascending(a.sector, b.sector) || d3.ascending(a.ticker, b.ticker));

  const marketCaps = data.filter(d => d.marketCap).map(d => d.marketCap);

  const radiusScale = d3.scaleSqrt()
    .domain([d3.min(marketCaps), d3.max(marketCaps)])
    .range([18, 58]);

  data.forEach(d => {
    d.radius = d.marketCap ? radiusScale(d.marketCap) : 22;
    d.x = sectorCenters[d.sector].x;
    d.y = sectorCenters[d.sector].y;
  });

  addLegend();

  const tableRows = d3.select('#stock-table tbody')
    .selectAll('tr')
    .data(data, d => d.ticker)
    .enter()
    .append('tr')
    .attr('class', 'data-row')
    .on('click', (_, d) => setSelected(d.ticker));

  tableRows.html(d => `
    <td>${d.ticker}</td>
    <td>${d.fullName}</td>
    <td>${d.sector}</td>
    <td>${formatMarketCap(d.marketCap)}</td>
  `);

  const node = svg.append('g')
    .attr('class', 'nodes-layer')
    .selectAll('g.node')
    .data(data, d => d.ticker)
    .enter()
    .append('g')
    .attr('class', 'node')
    .style('cursor', 'pointer')
    .on('mouseenter', showTooltip)
    .on('mouseleave', hideTooltip)
    .on('click', (event, d) => {
      setSelected(d.ticker);
      event.stopPropagation();
    });

  node.append('circle')
    .attr('r', d => d.radius)
    .attr('fill', d => color(d.sector));

  node.append('text')
    .attr('text-anchor', 'middle')
    .attr('dy', '0.35em')
    .text(d => d.ticker);

  svg.on('click', () => {
    selectedTicker = null;
    renderSelection();
  });

  const simulation = d3.forceSimulation(data)
    .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.16))
    .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.16))
    .force('charge', d3.forceManyBody().strength(1))
    .force('collide', d3.forceCollide(d => d.radius + 3).iterations(2))
    .stop();

  for (let i = 0; i < 250; i += 1) {
    simulation.tick();
  }

  node.attr('transform', d => `translate(${d.x}, ${d.y})`);
});
